# owner: platform
"""Absence notices that go home to parents."""

from datetime import date
from typing import List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

LETTER = (
    "Dear Parent or Guardian,\n\n"
    "{name} was marked absent on {count}: {dates}.\n\n"
    "Please contact the school office with questions.\n"
)

def _check_ids(student: Student, marks: List[Mark]) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id} is not for "
                f"{student.student_id}"
            )

def _letter(student: Student, missed: List[date]) -> str:
    name = f"{student.first_name} {student.last_name}"
    dates = ", ".join(when.isoformat() for when in missed)
    noun = "day" if len(missed) == 1 else "days"
    count = f"{len(missed)} {noun}"
    return LETTER.format(
        name=name, count=count, dates=dates
    )

# ---
def notice_text(student: Student, marks: List[Mark]) -> str:
    """Parent note listing the days a student missed."""
    _check_ids(student, marks)
    missed = days_missed(marks)
    if not missed:
        raise ValueError("no absences to write about")
    return _letter(student, missed)
